package dev.vneca.test.unified;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.math.BigInteger;import java.util.*;import java.io.*;import org.bouncycastle.asn1.x500.X500Name;import org.bouncycastle.asn1.x509.*;import org.bouncycastle.cert.jcajce.*;import org.bouncycastle.cert.*;import org.bouncycastle.operator.jcajce.*;import org.bouncycastle.cms.*;import org.bouncycastle.cms.jcajce.*;

/** Controlled offline vectors only. Ephemeral private keys stay in memory; no runtime trust/grant. */
public class VerifierVectors {
 static void pem(Path p,String label,byte[] b)throws Exception{Files.writeString(p,"-----BEGIN "+label+"-----\n"+Base64.getMimeEncoder(64,new byte[]{10}).encodeToString(b)+"\n-----END "+label+"-----\n");}
 static X509CertificateHolder cert(KeyPair subject,KeyPair issuer,X500Name name,X500Name issuerName,boolean root,long serial)throws Exception{var now=new Date();var b=new JcaX509v3CertificateBuilder(issuerName,BigInteger.valueOf(serial),new Date(now.getTime()-60000),new Date(now.getTime()+3600000),name,subject.getPublic());b.addExtension(Extension.basicConstraints,true,new BasicConstraints(root));b.addExtension(Extension.keyUsage,true,new KeyUsage(root?KeyUsage.keyCertSign|KeyUsage.cRLSign:KeyUsage.digitalSignature));return b.build(new JcaContentSignerBuilder("SHA256withRSA").build(issuer.getPrivate()));}
 static byte[] crl(KeyPair root,X500Name name,boolean revoked)throws Exception{var b=new X509v2CRLBuilder(name,new Date(System.currentTimeMillis()-60000));b.setNextUpdate(new Date(System.currentTimeMillis()+3600000));if(revoked)b.addCRLEntry(BigInteger.TWO,new Date(System.currentTimeMillis()-30000),1);return b.build(new JcaContentSignerBuilder("SHA256withRSA").build(root.getPrivate())).getEncoded();}
 public static void main(String[]a)throws Exception{
  Path dir=Path.of(a[0]).toAbsolutePath();Files.createDirectories(dir);var rsa=KeyPairGenerator.getInstance("RSA");rsa.initialize(2048);var root=rsa.generateKeyPair();var leaf=rsa.generateKeyPair();X500Name name=new X500Name("CN=CONTROLLED OFFLINE VECTOR ROOT NOT PLATFORM AUTHORITY"),identity=new X500Name("CN=CONTROLLED VECTOR SIGNER NOT REAL IDENTITY");var rootCert=cert(root,root,name,name,true,1);var leafCert=cert(leaf,root,identity,name,false,2);pem(dir.resolve("root.pem"),"CERTIFICATE",rootCert.getEncoded());pem(dir.resolve("leaf.pem"),"CERTIFICATE",leafCert.getEncoded());pem(dir.resolve("chain.pem"),"CERTIFICATE",rootCert.getEncoded());pem(dir.resolve("good.crl.pem"),"X509 CRL",crl(root,name,false));pem(dir.resolve("revoked.crl.pem"),"X509 CRL",crl(root,name,true));
  byte[] document="Controlled non-personal detached CMS bytes\n".getBytes(StandardCharsets.UTF_8);Files.write(dir.resolve("input.bin"),document);Files.writeString(dir.resolve("wrong.bin"),"Changed original");
  var gen=new CMSSignedDataGenerator();gen.addSignerInfoGenerator(new JcaSignerInfoGeneratorBuilder(new JcaDigestCalculatorProviderBuilder().build()).build(new JcaContentSignerBuilder("SHA256withRSA").build(leaf.getPrivate()),new JcaX509CertificateConverter().getCertificate(leafCert)));gen.addCertificates(new org.bouncycastle.util.CollectionStore<>(List.of(leafCert)));Files.write(dir.resolve("signed.cms"),gen.generate(new CMSProcessableByteArray(document),false).getEncoded());
  byte[] source="<Controlled><Value>Non personal test</Value></Controlled>".getBytes(StandardCharsets.UTF_8);Files.write(dir.resolve("input.xml"),source);var f=javax.xml.parsers.DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);var xml=f.newDocumentBuilder().parse(new ByteArrayInputStream(source));var factory=javax.xml.crypto.dsig.XMLSignatureFactory.getInstance("DOM");var reference=factory.newReference("",factory.newDigestMethod(javax.xml.crypto.dsig.DigestMethod.SHA256,null),List.of(factory.newTransform(javax.xml.crypto.dsig.Transform.ENVELOPED,(javax.xml.crypto.dsig.spec.TransformParameterSpec)null)),null,null);var info=factory.newSignedInfo(factory.newCanonicalizationMethod(javax.xml.crypto.dsig.CanonicalizationMethod.INCLUSIVE,(javax.xml.crypto.dsig.spec.C14NMethodParameterSpec)null),factory.newSignatureMethod(javax.xml.crypto.dsig.SignatureMethod.RSA_SHA256,null),List.of(reference));var context=new javax.xml.crypto.dsig.dom.DOMSignContext(leaf.getPrivate(),xml.getDocumentElement());factory.newXMLSignature(info,null).sign(context);var output=new ByteArrayOutputStream();javax.xml.transform.TransformerFactory.newInstance().newTransformer().transform(new javax.xml.transform.dom.DOMSource(xml),new javax.xml.transform.stream.StreamResult(output));Files.write(dir.resolve("signed.xml"),output.toByteArray());Files.writeString(dir.resolve("tampered.xml"),new String(output.toByteArray(),StandardCharsets.UTF_8).replace("Non personal test","Changed test data"));
  int passed=0;for(var c:List.of(new String[]{"CMS","signed.cms","input.bin","good.crl.pem","0"},new String[]{"CMS","signed.cms","wrong.bin","good.crl.pem","1"},new String[]{"CMS","signed.cms","input.bin","revoked.crl.pem","1"},new String[]{"XML","signed.xml","input.xml","good.crl.pem","0"},new String[]{"XML","tampered.xml","input.xml","good.crl.pem","1"},new String[]{"XML","signed.xml","input.xml","revoked.crl.pem","1"})){
   var command=new ArrayList<String>(List.of(Path.of(System.getProperty("java.home"),"bin","java").toString(),"-cp",System.getProperty("java.class.path"),"dev.vneca.test.unified.VerifyResult",c[0],dir.resolve(c[1]).toString(),dir.resolve(c[2]).toString(),dir.resolve("leaf.pem").toString(),dir.resolve("root.pem").toString(),dir.resolve("chain.pem").toString(),dir.resolve(c[3]).toString()));var process=new ProcessBuilder(command).redirectErrorStream(true).start();String result=new String(process.getInputStream().readAllBytes(),StandardCharsets.UTF_8);int exit=process.waitFor();if(exit!=Integer.parseInt(c[4]))throw new IllegalStateException("Controlled verifier vector failed "+c[0]+" "+c[1]+" "+result);passed++;
  }
  System.out.println("{\"classification\":\"CONTROLLED_OFFLINE_VECTORS_NOT_PROVIDER_UAT\",\"passed\":"+passed+",\"failed\":0,\"privateKeysWritten\":0,\"runtimeAuthorityChanges\":0}");
 }
}
